(5250406, 764048, 54446, '<td valign="top">This epitomizes my view of the personality of many cats.  You''ve captured an interesting and unique pose.  Great job!  8</td>', 'This epitomizes my view of the personality of many cats.  You''ve captured an interesting and unique pose.  Great job!  8', '2009-02-11 10:07:56.000000', NULL, 1),
(5250407, 763406, 54446, '<td valign="top">Good gray scale image.  Works very well to throw attention to the great dog face.  Wonderful composition and good detail in the shadows.</td>', 'Good gray scale image.  Works very well to throw attention to the great dog face.  Wonderful composition and good detail in the shadows.', '2009-02-11 10:08:43.000000', NULL, 1),
