(5252193, 764594, 63495, '<td valign="top">Enter your comment here, and then ca//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=764397#st your vote...nice dof</td>', 'Enter your comment here, and then ca//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=764397#st your vote...nice dof', '2009-02-11 22:23:29.000000', NULL, 1),
