(5253497, 764090, 29748, '<td valign="top">I think you used a DOF that was too shallow.  The front of the bread is in complete focus, but the Hamster seems a little( not alot) soft to me.</td>', 'I think you used a DOF that was too shallow.  The front of the bread is in complete focus, but the Hamster seems a little( not alot) soft to me.', '2009-02-12 14:58:50.000000', NULL, 1),
(5253500, 764354, 29748, '<td valign="top">The lighting is too dark, and the shower doors and the towel are busy and distracting.</td>', 'The lighting is too dark, and the shower doors and the towel are busy and distracting.', '2009-02-12 14:59:23.000000', NULL, 1),
(5253501, 763185, 29748, '<td valign="top">cute kitty.</td>', 'cute kitty.', '2009-02-12 14:59:34.000000', NULL, 1),
